import React, { useEffect, useState, useRef } from 'react';
import { supabase } from 'services/supabaseClient';

interface AnalyticsData {
  total: number;
  clients: number;
  freelancers: number;
  suspended: number;
  growthByMonth: { month: string; clients: number; freelancers: number }[];
  topLocations: { name: string; count: number }[];
  topSkills: { name: string; count: number }[];
}

const ORANGE = '#EA580C';
const NAVY = '#0F172A';
const SLATE = '#64748B';
// const LIGHT = '#F8FAFC';
const BORDER = '#E2E8F0';

// ── tiny animated counter ──────────────────────────────────────────────
function AnimatedNumber({ value }: { value: number }) {
  const [display, setDisplay] = useState(0);
  useEffect(() => {
    let start = 0;
    const step = Math.ceil(value / 40);
    const t = setInterval(() => {
      start += step;
      if (start >= value) { setDisplay(value); clearInterval(t); }
      else setDisplay(start);
    }, 20);
    return () => clearInterval(t);
  }, [value]);
  return <>{display.toLocaleString()}</>;
}

// ── bar chart ──────────────────────────────────────────────────────────
function BarChart({ data }: { data: AnalyticsData['growthByMonth'] }) {
  const max = Math.max(...data.flatMap(d => [d.clients, d.freelancers]), 1);
  return (
    <div style={{ display: 'flex', alignItems: 'flex-end', gap: 10, height: 140, padding: '0 4px' }}>
      {data.map((d, i) => (
        <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3 }}>
          <div style={{ display: 'flex', alignItems: 'flex-end', gap: 3, height: 110 }}>
            <div
              style={{
                width: 14,
                height: `${(d.clients / max) * 100}%`,
                background: ORANGE,
                borderRadius: '4px 4px 0 0',
                minHeight: 4,
                transition: 'height 0.8s cubic-bezier(.4,0,.2,1)',
                animationDelay: `${i * 60}ms`,
              }}
              title={`Clients: ${d.clients}`}
            />
            <div
              style={{
                width: 14,
                height: `${(d.freelancers / max) * 100}%`,
                background: NAVY,
                borderRadius: '4px 4px 0 0',
                minHeight: 4,
                transition: 'height 0.8s cubic-bezier(.4,0,.2,1)',
              }}
              title={`Freelancers: ${d.freelancers}`}
            />
          </div>
          <span style={{ fontSize: 9, color: SLATE, letterSpacing: 0.3 }}>{d.month}</span>
        </div>
      ))}
    </div>
  );
}

// ── donut chart ────────────────────────────────────────────────────────
function DonutChart({ clients, freelancers, suspended }: { clients: number; freelancers: number; suspended: number }) {
  const total = clients + freelancers + suspended || 1;
  const r = 52;
  const circ = 2 * Math.PI * r;
  const segments = [
    { value: clients,     color: ORANGE,    label: 'Clients' },
    { value: freelancers, color: NAVY,      label: 'Freelancers' },
    { value: suspended,   color: '#CBD5E1', label: 'Suspended' },
  ];
  let offset = 0;
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 24 }}>
      <svg width={130} height={130} viewBox="0 0 130 130">
        <circle cx={65} cy={65} r={r} fill="none" stroke={BORDER} strokeWidth={18} />
        {segments.map((seg, i) => {
          const dash = (seg.value / total) * circ;
          const gap = circ - dash;
          const el = (
            <circle
              key={i}
              cx={65} cy={65} r={r}
              fill="none"
              stroke={seg.color}
              strokeWidth={18}
              strokeDasharray={`${dash} ${gap}`}
              strokeDashoffset={-offset}
              strokeLinecap="butt"
              style={{ transform: 'rotate(-90deg)', transformOrigin: '65px 65px', transition: 'stroke-dasharray 1s ease' }}
            />
          );
          offset += dash;
          return el;
        })}
        <text x={65} y={60} textAnchor="middle" fontSize={20} fontWeight={700} fill={NAVY}>{Math.round((clients / total) * 100)}%</text>
        <text x={65} y={76} textAnchor="middle" fontSize={10} fill={SLATE}>Clients</text>
      </svg>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {segments.map((seg, i) => (
          <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{ width: 10, height: 10, borderRadius: 3, background: seg.color, flexShrink: 0 }} />
            <span style={{ fontSize: 12, color: SLATE }}>{seg.label}</span>
            <span style={{ fontSize: 12, fontWeight: 700, color: NAVY, marginLeft: 'auto', paddingLeft: 12 }}>
              {seg.value}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── horizontal bar ─────────────────────────────────────────────────────
function HBar({ label, count, max, color }: { label: string; count: number; max: number; color: string }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
      <span style={{ fontSize: 12, color: SLATE, width: 100, flexShrink: 0, textOverflow: 'ellipsis', overflow: 'hidden', whiteSpace: 'nowrap' }}>{label}</span>
      <div style={{ flex: 1, height: 6, background: BORDER, borderRadius: 99 }}>
        <div style={{ height: '100%', width: `${(count / max) * 100}%`, background: color, borderRadius: 99, transition: 'width 1s ease' }} />
      </div>
      <span style={{ fontSize: 11, fontWeight: 700, color: NAVY, width: 24, textAlign: 'right' }}>{count}</span>
    </div>
  );
}

// ── stat card ──────────────────────────────────────────────────────────
function StatCard({ label, value, sub, accent }: { label: string; value: number; sub: string; accent: string }) {
  return (
    <div style={{
      background: '#fff',
      border: `1px solid ${BORDER}`,
      borderRadius: 16,
      padding: '20px 24px',
      display: 'flex',
      flexDirection: 'column',
      gap: 6,
      position: 'relative',
      overflow: 'hidden',
    }}>
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 3, background: accent, borderRadius: '16px 16px 0 0' }} />
      <span style={{ fontSize: 11, fontWeight: 600, color: SLATE, textTransform: 'uppercase', letterSpacing: 1 }}>{label}</span>
      <span style={{ fontSize: 32, fontWeight: 800, color: NAVY, lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>
        <AnimatedNumber value={value} />
      </span>
      <span style={{ fontSize: 12, color: SLATE }}>{sub}</span>
    </div>
  );
}

// ── main component ─────────────────────────────────────────────────────
const UserAnalytics: React.FC = () => {
  const [data, setData] = useState<AnalyticsData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      try {
        const [profilesRes, userTypesRes, locationsRes, skillsRes] = await Promise.all([
          supabase.from('profiles').select('user_type_id, location_id, skills_id, suspended_at, created_at'),
          supabase.from('user_types').select('id, type'),
          supabase.from('locations').select('id, location'),
          supabase.from('skills').select('id, name'),
        ]);

        const profiles = profilesRes.data ?? [];
        const typeMap = new Map((userTypesRes.data ?? []).map(r => [r.id, r.type?.toLowerCase()]));
        const locMap  = new Map((locationsRes.data ?? []).map(r => [r.id, r.location]));
        const skillMap = new Map((skillsRes.data ?? []).map(r => [r.id, r.name]));

        let clients = 0, freelancers = 0, suspended = 0;
        const locationCount: Record<string, number> = {};
        const skillCount: Record<string, number>    = {};
        const monthMap: Record<string, { clients: number; freelancers: number }> = {};

        profiles.forEach(p => {
          const types: string[] = Array.isArray(p.user_type_id) ? p.user_type_id : [];
          const isClient     = types.some(id => typeMap.get(id) === 'hire talent');
          const isFreelancer = types.some(id => typeMap.get(id) === 'find work');
          if (p.suspended_at) suspended++;
          else if (isClient)     clients++;
          else if (isFreelancer) freelancers++;

          // locations
          const locs: string[] = Array.isArray(p.location_id) ? p.location_id : [];
          locs.forEach(lid => {
            const name = locMap.get(lid);
            if (name) locationCount[name] = (locationCount[name] || 0) + 1;
          });

          // skills
          const skills: string[] = Array.isArray(p.skills_id) ? p.skills_id : [];
          skills.forEach(sid => {
            const name = skillMap.get(sid);
            if (name) skillCount[name] = (skillCount[name] || 0) + 1;
          });

          // growth by month (last 6)
          if (p.created_at) {
            const d = new Date(p.created_at);
            const key = d.toLocaleString('default', { month: 'short' });
            if (!monthMap[key]) monthMap[key] = { clients: 0, freelancers: 0 };
            if (isClient)     monthMap[key].clients++;
            if (isFreelancer) monthMap[key].freelancers++;
          }
        });

        // last 6 months ordered
        const months: string[] = [];
        for (let i = 5; i >= 0; i--) {
          const d = new Date();
          d.setMonth(d.getMonth() - i);
          months.push(d.toLocaleString('default', { month: 'short' }));
        }
        const growthByMonth = months.map(m => ({
          month: m,
          clients: monthMap[m]?.clients ?? 0,
          freelancers: monthMap[m]?.freelancers ?? 0,
        }));

        const topLocations = Object.entries(locationCount)
          .sort((a, b) => b[1] - a[1]).slice(0, 5)
          .map(([name, count]) => ({ name, count }));

        const topSkills = Object.entries(skillCount)
          .sort((a, b) => b[1] - a[1]).slice(0, 5)
          .map(([name, count]) => ({ name, count }));

        setData({ total: profiles.length, clients, freelancers, suspended, growthByMonth, topLocations, topSkills });
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  if (loading) return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: 300, color: SLATE, fontFamily: "'DM Sans', sans-serif" }}>
      <div style={{ textAlign: 'center' }}>
        <div style={{ width: 36, height: 36, border: `3px solid ${BORDER}`, borderTop: `3px solid ${ORANGE}`, borderRadius: '50%', animation: 'spin 0.8s linear infinite', margin: '0 auto 12px' }} />
        Loading analytics…
      </div>
      <style>{`@keyframes spin { to { transform: rotate(360deg) } }`}</style>
    </div>
  );

  if (!data) return null;

  const maxLoc   = Math.max(...data.topLocations.map(l => l.count), 1);
  const maxSkill = Math.max(...data.topSkills.map(s => s.count), 1);
  const activeRate = data.total > 0 ? Math.round(((data.total - data.suspended) / data.total) * 100) : 0;

  return (
    <div style={{ fontFamily: "'DM Sans', 'Helvetica Neue', sans-serif", color: NAVY }}>

      {/* header */}
      <div style={{ marginBottom: 24 }}>
        <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: NAVY }}>User Analytics</h2>
        <p style={{ margin: '4px 0 0', fontSize: 13, color: SLATE }}>Real-time snapshot of your platform users</p>
      </div>

      {/* stat cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 16, marginBottom: 24 }}>
        <StatCard label="Total Users"  value={data.total}       sub="All registered accounts" accent={NAVY} />
        <StatCard label="Clients"      value={data.clients}     sub="Hire talent accounts"    accent={ORANGE} />
        <StatCard label="Freelancers"  value={data.freelancers} sub="Find work accounts"      accent="#0EA5E9" />
        <StatCard label="Suspended"    value={data.suspended}   sub={`${activeRate}% active rate`} accent="#CBD5E1" />
      </div>

      {/* charts row */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16, marginBottom: 16 }}>

        {/* growth chart */}
        <div style={{ background: '#fff', border: `1px solid ${BORDER}`, borderRadius: 16, padding: 24 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: NAVY }}>Growth Over Time</div>
              <div style={{ fontSize: 11, color: SLATE, marginTop: 2 }}>Last 6 months</div>
            </div>
            <div style={{ display: 'flex', gap: 12 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                <div style={{ width: 8, height: 8, borderRadius: 2, background: ORANGE }} />
                <span style={{ fontSize: 11, color: SLATE }}>Clients</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                <div style={{ width: 8, height: 8, borderRadius: 2, background: NAVY }} />
                <span style={{ fontSize: 11, color: SLATE }}>Freelancers</span>
              </div>
            </div>
          </div>
          <BarChart data={data.growthByMonth} />
        </div>

        {/* donut */}
        <div style={{ background: '#fff', border: `1px solid ${BORDER}`, borderRadius: 16, padding: 24 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: NAVY, marginBottom: 4 }}>User Breakdown</div>
          <div style={{ fontSize: 11, color: SLATE, marginBottom: 20 }}>Distribution by type</div>
          <DonutChart clients={data.clients} freelancers={data.freelancers} suspended={data.suspended} />
        </div>
      </div>

      {/* bottom row */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>

        {/* top locations */}
        <div style={{ background: '#fff', border: `1px solid ${BORDER}`, borderRadius: 16, padding: 24 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Top Locations</div>
          <div style={{ fontSize: 11, color: SLATE, marginBottom: 16 }}>Where your users are based</div>
          {data.topLocations.length > 0 ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {data.topLocations.map((l, i) => (
                <HBar key={i} label={l.name} count={l.count} max={maxLoc} color={ORANGE} />
              ))}
            </div>
          ) : <span style={{ fontSize: 13, color: '#CBD5E1' }}>No location data</span>}
        </div>

        {/* top skills */}
        <div style={{ background: '#fff', border: `1px solid ${BORDER}`, borderRadius: 16, padding: 24 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: NAVY, marginBottom: 4 }}>Top Skills</div>
          <div style={{ fontSize: 11, color: SLATE, marginBottom: 16 }}>Most common user skills</div>
          {data.topSkills.length > 0 ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {data.topSkills.map((s, i) => (
                <HBar key={i} label={s.name} count={s.count} max={maxSkill} color={NAVY} />
              ))}
            </div>
          ) : <span style={{ fontSize: 13, color: '#CBD5E1' }}>No skill data</span>}
        </div>
      </div>

    </div>
  );
};

export default UserAnalytics;
